scwin.checkValue = function(id1, id2) {
    if (scwin.__getDom(id1)) {
        return scwin.__getJq("#" + id1).text();
    } else if (scwin.__getDom(id2)) {
        return scwin.__getJq("#" + id2).text();
    }
    return "";
}
